trace.detail:
{
  "summary": "Renewal request from Acme Cloud Services with a 12% price increase needs contract terms, SLA performance, and invoice history checked before drafting a response.",
  "reply_type": "vendor_email",
  "steps": [
    {
      "id": 1,
      "agent": "retriever",
      "task": "List and read the current Acme Cloud Services contract to find current pricing, renewal terms, and notice periods; check SLA performance records for the contract period using the SLA credit calculator to determine any credits owed to us; review recent invoices/payment records for currency and billing details; if any amounts are in USD or another foreign currency, use the currency converter to express them in our reporting currency.",
      "why": "The retriever must gather all contract terms, SLA credit obligations, and invoice/currency facts needed to evaluate the proposed 12% increase and any offsets owed to us."
    },
    {
      "id": 2,
      "agent": "executor",
      "task": "Draft the final vendor email response to Acme Cloud Services addressing the renewal request, referencing current contract terms, confirming or countering the 12% price increase, and noting any SLA credits owed to us that should offset the new pricing.",
      "why": "The executor synthesizes the gathered facts into the final reply for human review and approval."
    }
  ],
  "escalate": null
}
